IPDAMS_REGISTRY_DATA;
    public static function rows(): array {
        static $rows = null;
        if ($rows === null) $rows = json_decode(self::REGISTRY_JSON, true, 512, JSON_THROW_ON_ERROR);
        return $rows;
    }
    public static function find(string $id): ?array {
        foreach(self::rows() as $row) if ($row['id']===$id) return $row;
        return null;
    }
    public static function tier(int $unitCents, int $thresholdCents): string {
        if ($unitCents < 0 || $thresholdCents <= 0) throw new InvalidArgumentException('Invalid property valuation');
        return $unitCents >= $thresholdCents ? 'HV' : 'LV';
    }
    public static function officialCode(array $row, ?string $tier): ?string {
        if (($row['mode']??'')==='REFERENCE')return ($row['reference_code']??'') ?: null;
        if (($row['mode']??'')!=='HV_LV' || !in_array($tier,['HV','LV'],true))return null;
        return ($row[$tier==='HV'?'hv_code':'lv_code']??'') ?: null;
    }
}
